// ===== CẤU HÌNH: dán Page Access Token vào đây =====
const PAGE_TOKEN = 'DAN_PAGE_ACCESS_TOKEN_VAO_DAY';

// Kịch bản trả lời theo từ khóa (sửa tùy cửa hàng)
const rules = [
  { keys: ['giá', 'gia', 'bao nhiêu'], reply: 'Dạ, bảng giá shop: Áo thun 150k, Quần jean 350k. Anh/chị cần mẫu nào ạ?' },
  { keys: ['ship', 'giao hàng', 'phí ship'], reply: 'Shop giao toàn quốc, phí ship 30k, freeship đơn từ 500k ạ.' },
  { keys: ['địa chỉ', 'dia chi', 'ở đâu'], reply: 'Shop ở 123 Nguyễn Trãi, Hà Nội. Mở cửa 8h–21h ạ.' },
  { keys: ['đặt hàng', 'mua', 'order'], reply: 'Anh/chị gửi giúp shop: Tên + SĐT + Địa chỉ + Sản phẩm, shop lên đơn ngay ạ!' },
];
const fallback = 'Cảm ơn anh/chị đã nhắn tin! Gõ "giá", "ship", "địa chỉ" hoặc "đặt hàng" để được hỗ trợ nhanh ạ.';

const out = [];
for (const entry of $json.body?.entry ?? []) {
  for (const ev of entry.messaging ?? []) {
    const text = ev.message?.text;
    if (!text || ev.message?.is_echo) continue;
    const lower = text.toLowerCase();
    const rule = rules.find(r => r.keys.some(k => lower.includes(k)));
    out.push({ json: { psid: ev.sender.id, text, reply: rule ? rule.reply : fallback, token: PAGE_TOKEN } });
  }
}
return out;
